css:
.brandsig-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2a2620;
    background: linear-gradient(165deg, #faf7f0 0%, #f3f0e6 55%, #eef1e8 100%);
    border-radius: 18px;
}

.brandsig-container * {
    box-sizing: border-box;
}

.brandsig-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #2f4a3a 0%, #3f6b4d 55%, #6b8f5a 100%);
    color: #f6faf2;
    border-radius: 16px;
    margin-bottom: 18px;
    box-shadow: 0 14px 34px rgba(47, 74, 58, 0.30);
}

.brandsig-header h1 {
    margin: 10px 0 10px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.brandsig-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #f4d9a0;
    background: rgba(244, 217, 160, 0.14);
    border: 1px solid rgba(244, 217, 160, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.brandsig-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.55;
    color: #dcead0;
}

.brandsig-brands {
    display: flex;
    align-items: stretch;
    gap: 12px;
    margin-bottom: 18px;
}

.brandsig-brand {
    flex: 1;
    background: #ffffff;
    border-radius: 14px;
    padding: 14px 18px;
    box-shadow: 0 4px 14px rgba(42, 38, 32, 0.08);
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.brandsig-brand-vista { border-left: 5px solid #6b8f5a; }
.brandsig-brand-polje { border-left: 5px solid #c2823a; }

.brandsig-brand-name {
    font-weight: 800;
    font-size: 1.05rem;
    color: #2f4a3a;
}

.brandsig-brand-polje .brandsig-brand-name { color: #b06f1f; }

.brandsig-brand-meta {
    font-size: 0.82rem;
    color: #6b6356;
    line-height: 1.4;
}

.brandsig-brand-vs {
    align-self: center;
    font-size: 1.1rem;
    font-weight: 800;
    color: #8a8475;
    text-transform: uppercase;
    letter-spacing: 1px;
}

.brandsig-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #5a5446;
    margin-bottom: 16px;
    padding: 4px 4px;
}

.brandsig-period-counter #currentDay,
.brandsig-period-counter #maxPeriods {
    font-weight: 800;
    color: #6b8f5a;
}

.brandsig-round-name {
    background: rgba(107, 143, 90, 0.16);
    color: #4d6e3c;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.brandsig-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #a8691a;
    background: rgba(194, 130, 58, 0.14);
    border: 1px solid rgba(194, 130, 58, 0.30);
    padding: 4px 12px;
    border-radius: 999px;
}

.brandsig-hero {
    text-align: center;
    background: #ffffff;
    border-radius: 16px;
    padding: 22px 18px 18px;
    margin-bottom: 16px;
    box-shadow: 0 8px 22px rgba(42, 38, 32, 0.10);
    border-top: 5px solid #6b8f5a;
}

.brandsig-hero-label {
    font-size: 0.82rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #6b7d5e;
}

.brandsig-hero-value {
    font-size: 3.6rem;
    font-weight: 800;
    line-height: 1.05;
    margin: 4px 0 4px;
    color: #3f6b4d;
    font-variant-numeric: tabular-nums;
}

.brandsig-hero.brandsig-intent-danger { border-top-color: #c0392b; }
.brandsig-hero.brandsig-intent-danger .brandsig-hero-value { color: #c0392b; }
.brandsig-hero.brandsig-intent-warn { border-top-color: #c2823a; }
.brandsig-hero.brandsig-intent-warn .brandsig-hero-value { color: #b06f1f; }
.brandsig-hero.brandsig-intent-good { border-top-color: #4d8a3a; }
.brandsig-hero.brandsig-intent-good .brandsig-hero-value { color: #4d8a3a; }

.brandsig-hero-sub {
    font-size: 0.82rem;
    color: #7a7264;
    line-height: 1.4;
    max-width: 620px;
    margin: 0 auto;
}

.brandsig-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.brandsig-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 6px 16px rgba(42, 38, 32, 0.08);
    border-top: 4px solid #6b8f5a;
}

.brandsig-card-warmth { border-top-color: #c2823a; }
.brandsig-card-competence { border-top-color: #3f7a8f; }
.brandsig-card-morality { border-top-color: #7d5fc0; }
.brandsig-card-romi { border-top-color: #6b8f5a; }

.brandsig-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #7a7264;
}

.brandsig-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #2f4a3a;
    font-variant-numeric: tabular-nums;
}

.brandsig-card-warmth .brandsig-value { color: #b06f1f; }
.brandsig-card-competence .brandsig-value { color: #2f6679; }
.brandsig-card-morality .brandsig-value { color: #6b4fb0; }
.brandsig-card-romi .brandsig-value { color: #4d6e3c; }

.brandsig-sublabel {
    font-size: 0.76rem;
    color: #8a8275;
    line-height: 1.35;
}

.brandsig-card-morality.brandsig-morality-danger { border-top-color: #c0392b; }
.brandsig-card-morality.brandsig-morality-danger .brandsig-value { color: #c0392b; }
.brandsig-card-romi.brandsig-romi-good { border-top-color: #4d8a3a; }
.brandsig-card-romi.brandsig-romi-good .brandsig-value { color: #4d8a3a; }
.brandsig-card-romi.brandsig-romi-bad { border-top-color: #c0392b; }
.brandsig-card-romi.brandsig-romi-bad .brandsig-value { color: #c0392b; }

.brandsig-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #e3e0d4;
    color: #5a5446;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.brandsig-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #3f6b4d;
    font-weight: 800;
    font-variant-numeric: tabular-nums;
}

.brandsig-budget-bar.brandsig-budget-over #budgetDisplay { color: #c0392b; }

.brandsig-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #6b8f5a;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(42, 38, 32, 0.07);
}

.brandsig-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.brandsig-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #2f4a3a;
    margin-bottom: 6px;
}

.brandsig-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #4a4438;
}

.brandsig-briefing-text strong { color: #3f6b4d; }
.brandsig-briefing-text em { color: #b06f1f; font-style: italic; }

.brandsig-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(42, 38, 32, 0.07);
}

.brandsig-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #2f4a3a;
    border-bottom: 2px solid #ece8db;
    padding-bottom: 8px;
}

.brandsig-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #3a3528;
    margin: 14px 0 6px;
}

.brandsig-container select,
.brandsig-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #d2cdbe;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #ffffff;
    color: #2a2620;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.brandsig-container select:focus,
.brandsig-container input[type="number"]:focus {
    outline: none;
    border-color: #6b8f5a;
    box-shadow: 0 0 0 3px rgba(107, 143, 90, 0.18);
}

.brandsig-container select option {
    background-color: #ffffff;
    color: #2a2620;
}

.brandsig-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #6b8f5a;
}

.brandsig-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #5a5446;
    margin-top: 4px;
}

.brandsig-range-readout span {
    color: #3f6b4d;
    font-weight: 800;
}

.brandsig-hint {
    font-size: 0.8rem;
    color: #8a8275;
    margin-top: 6px;
    line-height: 1.4;
    font-style: italic;
}

.brandsig-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.brandsig-container .btn-primary {
    background: linear-gradient(135deg, #3f6b4d 0%, #6b8f5a 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(63, 107, 77, 0.32);
}

.brandsig-container .btn-primary:hover {
    filter: brightness(1.07);
}

.brandsig-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #d2cdbe;
    color: #6b6356;
    background: transparent;
}

.brandsig-coach {
    background: linear-gradient(160deg, #2f4a3a 0%, #38543f 100%);
    color: #e7f1de;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(47, 74, 58, 0.24);
}

.brandsig-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f4d9a0;
    margin-bottom: 8px;
}

.brandsig-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.brandsig-coach-body strong { color: #aee08f; }
.brandsig-coach-body em { color: #f4d9a0; font-style: italic; }

.brandsig-history,
.brandsig-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(42, 38, 32, 0.07);
}

.brandsig-history h3,
.brandsig-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #2f4a3a;
}

.brandsig-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #4a4438;
}

.brandsig-container table#usfHistoryTable th {
    background: #eef2e8;
    color: #4d6e3c;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #dce4d2;
}

.brandsig-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #efece2;
    color: #4a4438;
}

.brandsig-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f8faf4;
}

.brandsig-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .brandsig-container {
        padding: 14px;
    }
    .brandsig-header h1 {
        font-size: 1.7rem;
    }
    .brandsig-brands {
        flex-direction: column;
    }
    .brandsig-hero-value {
        font-size: 2.8rem;
    }
    .brandsig-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .brandsig-value {
        font-size: 2rem;
    }
    .brandsig-clock {
        margin-left: 0;
    }
    .brandsig-period-counter {
        font-size: 0.88rem;
    }
    .brandsig-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .brandsig-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 FIX B - completion / board-debrief scorecard (append-only, namespaced) ===== */
.bs-cm { padding: 12px 6px; text-align: center; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif; }
.bs-cm-heading { font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: #8a8397; margin-bottom: 6px; }
.bs-cm-verdict { font-size: 22px; font-weight: 700; color: #2a2438; margin-bottom: 8px; }
.bs-cm-score { font-size: 16px; color: #2a2438; margin-bottom: 16px; }
.bs-cm-score strong { color: #b0417a; }
.bs-cm-sub { font-size: 11px; letter-spacing: .06em; text-transform: uppercase; color: #8a8397; margin-bottom: 8px; }
.bs-cm-targets { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; margin-bottom: 16px; }
.bs-cm-target { display: inline-flex; align-items: center; gap: 6px; padding: 6px 11px; border-radius: 20px; font-size: 13px; border: 1px solid transparent; }
.bs-cm-target.bs-cm-met { background: #f6e8f0; color: #8f2f63; border-color: #e6c2d6; }
.bs-cm-target.bs-cm-missed { background: #fdeceb; color: #9a342c; border-color: #f2c9c4; }
.bs-cm-tick { font-weight: 700; }
.bs-cm-metrics { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin-bottom: 16px; }
.bs-cm-metric { display: inline-flex; flex-direction: column; align-items: center; gap: 2px; padding: 9px 13px; background: #f4f1f6; border-radius: 8px; min-width: 88px; }
.bs-cm-metric span { font-size: 11px; letter-spacing: .03em; text-transform: uppercase; color: #8a8397; }
.bs-cm-metric strong { font-size: 16px; color: #2a2438; }
.bs-cm-insights { list-style: none; padding: 0; margin: 0 auto; max-width: 720px; text-align: left; }
.bs-cm-insights li { padding: 9px 13px; margin-bottom: 7px; background: #f7eef3; border-left: 3px solid #b0417a; border-radius: 4px; color: #33293a; font-size: 13px; line-height: 1.45; }
@media (max-width: 640px) { .bs-cm-metric { min-width: 68px; } .bs-cm-verdict { font-size: 19px; } }

