(function() {
    'use strict';

    class BrandSignalsAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Brand Signals`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Vista / Karst Foods).
            this.START_WARMTH = 72;
            this.START_COMPETENCE = 58;
            this.START_MORALITY = 49;
            this.START_INTENT = 55;       // % purchase intent
            this.TARGET_INTENT = 60;      // stabilization goal
            this.BUDGET = 14;             // EUR 14M marketing budget
            this.REVENUE = 95;            // EUR 95M brand revenue
            this.PREMIUM = 18;            // 18% price premium
            this.MARGIN_RATE = 0.42;      // assumed gross margin on incremental revenue

            // Concept truths (the modelled path).
            this.TRUE_CONSTRAINT = `morality`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    warmth: this.START_WARMTH,
                    competence: this.START_COMPETENCE,
                    morality: this.START_MORALITY,
                    intent: this.START_INTENT,
                    romi: 0,                       // running ROMI ratio (x)
                    spentTotal: 0,                 // cumulative EUR M deployed
                    substanceTotal: 0,             // cumulative substance EUR M
                    commsTotal: 0,                 // cumulative comms EUR M
                    premiumIntact: true,           // 18% premium defended
                    greenwashHit: false,           // a greenwashing backlash occurred
                    builtSubstance: false,         // a verifiable initiative was funded
                    factCheckSurvived: false,      // morality held under the journalist
                    warmthHistory: [this.START_WARMTH],
                    competenceHistory: [this.START_COMPETENCE],
                    moralityHistory: [this.START_MORALITY],
                    intentHistory: [this.START_INTENT],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the classic errors — a blind
                // click-through must NOT auto-win.
                state.decisions = {
                    constraint: `warmth`,
                    segment: `loyal`,
                    read: `awareness`,
                    initiative: `community`,
                    channel: `mass`,
                    map: `grabbag`,
                    substance: 2,
                    comms: 11,
                    sequence: `loudfirst`,
                    factcheck: `spin`,
                    price: `match`,
                    board: `reach`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const co = document.getElementById(`constraintInput`);
                const se = document.getElementById(`segmentInput`);
                const re = document.getElementById(`readInput`);
                if (co) decisions.constraint = co.value;
                if (se) decisions.segment = se.value;
                if (re) decisions.read = re.value;
            } else if (round === 2) {
                const ini = document.getElementById(`initiativeInput`);
                const ch = document.getElementById(`channelInput`);
                const mp = document.getElementById(`mapInput`);
                if (ini) decisions.initiative = ini.value;
                if (ch) decisions.channel = ch.value;
                if (mp) decisions.map = mp.value;
            } else if (round === 3) {
                const su = document.getElementById(`substanceInput`);
                const cm = document.getElementById(`commsInput`);
                const sq = document.getElementById(`sequenceInput`);
                if (su) decisions.substance = parseFloat(su.value);
                if (cm) decisions.comms = parseFloat(cm.value);
                if (sq) decisions.sequence = sq.value;
                if (!Number.isFinite(decisions.substance) || decisions.substance < 0) {
                    warn(`warn_substance_value`); return false;
                }
                if (!Number.isFinite(decisions.comms) || decisions.comms < 0) {
                    warn(`warn_comms_value`); return false;
                }
                if (decisions.substance + decisions.comms > this.BUDGET + 0.001) {
                    warn(`warn_budget_cap`); return false;
                }
            } else if (round === 4) {
                const fc = document.getElementById(`factcheckInput`);
                const pr = document.getElementById(`priceInput`);
                const bo = document.getElementById(`boardInput`);
                const cv = document.getElementById(`convictionInput`);
                if (fc) decisions.factcheck = fc.value;
                if (pr) decisions.price = pr.value;
                if (bo) decisions.board = bo.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            this._updateBriefing(state);
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let wDelta = 0, cDelta = 0, mDelta = 0;     // impression deltas
            let spend = 0, substanceSpend = 0, commsSpend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose: identify the binding constraint and the at-risk segment.
                switch (d.constraint) {
                    case `morality`: mDelta += 4; cDelta += 1; coachKey = `coach_r1_morality`; break;
                    case `competence`: cDelta += 2; coachKey = `coach_r1_competence`; break;
                    case `warmth`: wDelta += 3; mDelta -= 1; coachKey = `coach_r1_warmth`; break;
                    case `none`: wDelta += 1; cDelta += 1; mDelta += 1; coachKey = `coach_r1_none`; break;
                }
                switch (d.segment) {
                    case `under35`: mDelta += 2; break;
                    case `loyal`: mDelta -= 1; coachKey = `coach_r1_loyal`; break;
                    case `all`: break;
                }
                switch (d.read) {
                    case `chain`: cDelta += 1; mDelta += 2; if (d.constraint === `morality`) coachKey = `coach_r1_sharp`; break;
                    case `awareness`: wDelta += 1; coachKey = `coach_r1_awareness`; break;
                    case `price`: coachKey = `coach_r1_price`; break;
                }
                summaryKey = (d.constraint === `morality` && d.segment === `under35` && d.read === `chain`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Plan: map investments to impressions (no spend committed yet — a planning round).
                switch (d.initiative) {
                    case `audited`: ds.builtSubstance = true; mDelta += 6; cDelta += 4; coachKey = `coach_r2_audited`; break;
                    case `packaging`: ds.builtSubstance = true; cDelta += 4; mDelta += 2; break;
                    case `community`: wDelta += 5; mDelta -= 1; coachKey = `coach_r2_community`; break;
                    case `none`: mDelta -= 2; coachKey = `coach_r2_noinitiative`; break;
                }
                switch (d.channel) {
                    case `earned`: mDelta += 3; cDelta += 1; break;
                    case `mass`: wDelta += 2; if (!ds.builtSubstance) mDelta -= 2; break;
                    case `influencer`: wDelta += 2; mDelta -= 1; coachKey = `coach_r2_influencer`; break;
                }
                switch (d.map) {
                    case `explicit`: mDelta += 2; cDelta += 1; if (d.initiative === `audited`) coachKey = `coach_r2_mapped`; break;
                    case `grabbag`: coachKey = `coach_r2_grabbag`; break;
                    case `warmthtilt`: wDelta += 3; mDelta -= 2; coachKey = `coach_r2_warmthtilt`; break;
                }
                summaryKey = (d.initiative === `audited` && d.channel === `earned` && d.map === `explicit`) ? `sum_r2_good` :
                             (d.map === `grabbag` ? `sum_r2_grabbag` :
                             (d.map === `warmthtilt` ? `sum_r2_warmth` : `sum_r2_weak`));
            } else if (round === 3) {
                // Decide: commit the EUR 14M and sequence proof vs message.
                substanceSpend = d.substance;
                commsSpend = d.comms;
                spend = substanceSpend + commsSpend;

                const substanceShare = spend > 0 ? substanceSpend / spend : 0;

                // Substance moves morality & competence (especially when grounded).
                mDelta += substanceSpend * 1.6;
                cDelta += substanceSpend * 0.9;
                if (substanceSpend >= 3) ds.builtSubstance = true;

                // Communication amplifies — but only credible if substance backs it.
                if (substanceShare >= 0.30) {
                    // Grounded amplification: comms converts substance into perception & intent.
                    wDelta += commsSpend * 0.5;
                    cDelta += commsSpend * 0.4;
                    mDelta += commsSpend * 0.3;
                    coachKey = `coach_r3_grounded`;
                } else {
                    // Communication outruns substance -> greenwashing risk.
                    wDelta += commsSpend * 0.4;
                    mDelta -= commsSpend * 0.5;     // ungrounded claims lower morality
                    ds.greenwashHit = true;
                    coachKey = `coach_r3_ungrounded`;
                }

                // Sequencing: proof before amplification protects morality.
                switch (d.sequence) {
                    case `proExpress`: mDelta += 4; cDelta += 1; if (substanceShare >= 0.30) coachKey = `coach_r3_sequenced`; break;
                    case `simultaneous`: mDelta += 1; break;
                    case `loudfirst`: mDelta -= 4; ds.greenwashHit = true; coachKey = `coach_r3_loudfirst`; break;
                }

                ds.substanceTotal = Math.round((ds.substanceTotal + substanceSpend) * 10) / 10;
                ds.commsTotal = Math.round((ds.commsTotal + commsSpend) * 10) / 10;

                summaryKey = (substanceShare >= 0.30 && d.sequence !== `loudfirst`) ? `sum_r3_good` :
                             (ds.greenwashHit ? `sum_r3_greenwash` : `sum_r3_weak`);
            } else if (round === 4) {
                // Recover: fact-check, the price cut, the board.
                switch (d.factcheck) {
                    case `verified`:
                        if (ds.builtSubstance) { mDelta += 6; cDelta += 2; ds.factCheckSurvived = true; coachKey = `coach_r4_verified`; }
                        else { mDelta -= 7; ds.greenwashHit = true; coachKey = `coach_r4_hollow`; }
                        break;
                    case `spin`: mDelta -= 5; ds.greenwashHit = true; coachKey = `coach_r4_spin`; break;
                    case `quiet`: mDelta -= 3; coachKey = `coach_r4_quiet`; break;
                }
                switch (d.price) {
                    case `superiority`: ds.premiumIntact = true; cDelta += 2; mDelta += 1; coachKey = `coach_r4_superiority`; break;
                    case `match`: ds.premiumIntact = false; cDelta -= 4; wDelta -= 1; coachKey = `coach_r4_match`; break;
                    case `deeper`: ds.premiumIntact = false; cDelta -= 7; mDelta -= 2; coachKey = `coach_r4_deeper`; break;
                }
                switch (d.board) {
                    case `romi`: cDelta += 2; if (d.price === `superiority`) coachKey = `coach_r4_romi`; break;
                    case `reach`: cDelta -= 1; coachKey = `coach_r4_reach`; break;
                    case `spend`: coachKey = `coach_r4_spend`; break;
                }
                if (d.conviction >= 60 && ds.builtSubstance) { mDelta += 2; }
                else if (d.conviction >= 60 && !ds.builtSubstance) { mDelta -= 2; coachKey = `coach_r4_overclaim`; }

                summaryKey = (d.factcheck === `verified` && ds.builtSubstance && d.price === `superiority` && d.board === `romi`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // ---- Apply impression deltas (clamped 0–100). ----
            ds.warmth = Math.max(0, Math.min(100, Math.round((ds.warmth + wDelta) * 10) / 10));
            ds.competence = Math.max(0, Math.min(100, Math.round((ds.competence + cDelta) * 10) / 10));
            ds.morality = Math.max(0, Math.min(100, Math.round((ds.morality + mDelta) * 10) / 10));

            // ---- Purchase intent is DERIVED from impressions, morality-weighted,
            // because morality is the dimension under attack and the binding constraint.
            // Premium loss and greenwashing penalise intent directly. ----
            const impressionIndex = (ds.warmth * 0.25 + ds.competence * 0.30 + ds.morality * 0.45);
            // Map the impression index (0–100) onto an intent band roughly 35–78%.
            let intent = 35 + (impressionIndex - 40) * 0.72;
            if (!ds.premiumIntact) intent -= 4;        // matching the discount cheapens perceived superiority
            if (ds.greenwashHit) intent -= 3;          // a second credibility hit suppresses intent
            ds.intent = Math.max(0, Math.min(100, Math.round(intent * 10) / 10));

            // ---- ROMI is DERIVED: incremental margin from intent lift vs marketing spent. ----
            ds.spentTotal = Math.round((ds.spentTotal + spend) * 10) / 10;
            const intentLift = ds.intent - this.START_INTENT;                 // pts vs baseline
            // Each point of intent lift is modelled to convert ~EUR 1.05M incremental revenue.
            const incrementalRevenue = Math.max(-20, intentLift) * 1.05;
            const premiumFactor = ds.premiumIntact ? 1 : 0.7;                  // surrendered premium thins margin
            const incrementalMargin = incrementalRevenue * this.MARGIN_RATE * premiumFactor;
            const denom = ds.spentTotal > 0 ? ds.spentTotal : 1;
            ds.romi = Math.round((incrementalMargin / denom) * 100) / 100;

            ds.warmthHistory.push(ds.warmth);
            ds.competenceHistory.push(ds.competence);
            ds.moralityHistory.push(ds.morality);
            ds.intentHistory.push(ds.intent);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0 FIX A - persist the composite where the gradebook / reporting layer reads it
            const _c = this._composite(ds);
            ds.score = _c;
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = _c;
            return {
                period: state.currentPeriod,
                score: _c,
                overallScore: _c,
                warmth: ds.warmth,
                competence: ds.competence,
                morality: ds.morality,
                moralityDelta: Math.round(mDelta * 10) / 10,
                intent: ds.intent,
                intentLift: Math.round(intentLift * 10) / 10,
                romi: ds.romi,
                spend: Math.round(spend * 10) / 10,
                premiumIntact: ds.premiumIntact,
                greenwashHit: ds.greenwashHit,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtRomi(v) {
            const n = Number(v);
            if (!Number.isFinite(n) || (this._everSpent() === false)) return `—`;
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = n.toFixed(2);
            return (lang === `es` ? s.replace(`.`, `,`) : s) + `×`;
        }

        _everSpent() {
            const ds = window.mySimulation && window.mySimulation.state ? window.mySimulation.state.domainState : null;
            return !!(ds && ds.spentTotal > 0);
        }

        _fmtPct(v) {
            return `${Math.round(Number(v))}%`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`intentDisplay`, `domainState.intent`, (v) => {
                const n = Number(v);
                const hero = document.querySelector(`.brandsig-hero`);
                if (hero) {
                    hero.classList.toggle(`brandsig-intent-good`, n >= self.TARGET_INTENT);
                    hero.classList.toggle(`brandsig-intent-warn`, n >= 50 && n < self.TARGET_INTENT);
                    hero.classList.toggle(`brandsig-intent-danger`, n < 50);
                }
                return self._fmtPct(n);
            });

            uiManager.bind(`warmthDisplay`, `domainState.warmth`, (v) => `${Math.round(Number(v))}`);
            uiManager.bind(`competenceDisplay`, `domainState.competence`, (v) => `${Math.round(Number(v))}`);

            uiManager.bind(`moralityDisplay`, `domainState.morality`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.brandsig-card-morality`);
                if (card) card.classList.toggle(`brandsig-morality-danger`, n < 55);
                return `${Math.round(n)}`;
            });

            uiManager.bind(`romiDisplay`, `domainState.romi`, (v) => {
                const card = document.querySelector(`.brandsig-card-romi`);
                if (card) {
                    const spent = self._everSpent();
                    card.classList.toggle(`brandsig-romi-good`, spent && Number(v) >= 1.0);
                    card.classList.toggle(`brandsig-romi-bad`, spent && Number(v) < 0.5);
                }
                return self._fmtRomi(v);
            });

            // Budget readout (substance + comms sliders).
            const su = document.getElementById(`substanceInput`);
            const cm = document.getElementById(`commsInput`);
            const suR = document.getElementById(`substanceReadout`);
            const cmR = document.getElementById(`commsReadout`);
            const refresh = () => {
                if (su && suR) suR.textContent = self._fmtSlider(su.value);
                if (cm && cmR) cmR.textContent = self._fmtSlider(cm.value);
                const total = (su ? parseFloat(su.value) : 0) + (cm ? parseFloat(cm.value) : 0);
                const bar = document.querySelector(`.brandsig-budget-bar`);
                const bd = document.getElementById(`budgetDisplay`);
                if (bd) bd.textContent = `€${self._fmtSlider(total)}M / €14.0M`;
                if (bar) bar.classList.toggle(`brandsig-budget-over`, total > self.BUDGET + 0.001);
            };
            if (su) su.addEventListener(`input`, refresh);
            if (cm) cm.addEventListener(`input`, refresh);
            refresh();
        }

        _fmtSlider(v) {
            const n = Number(v);
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = (Math.round(n * 10) / 10).toFixed(1);
            return lang === `es` ? s.replace(`.`, `,`) : s;
        }

        getChartConfig() {
            return {
