                            {
                                label: `Purchase intent (%)`,
                                data: [],
                                borderColor: `#3f6b4d`,
                                backgroundColor: `rgba(63,107,77,0.12)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#3f6b4d`,
                                yAxisID: `y`
                            },
                            {
                                label: `Morality`,
                                data: [],
                                borderColor: `#7d5fc0`,
                                backgroundColor: `rgba(125,95,192,0.08)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#7d5fc0`,
                                yAxisID: `y`
                            },
                            {
                                label: `Competence`,
                                data: [],
                                borderColor: `#3f7a8f`,
                                backgroundColor: `rgba(63,122,143,0.06)`,
                                borderWidth: 2,
                                borderDash: [4, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#3f7a8f`,
                                yAxisID: `y`
                            },
                            {
                                label: `Warmth`,
                                data: [],
                                borderColor: `#c2823a`,
                                backgroundColor: `rgba(194,130,58,0.06)`,
                                borderWidth: 2,
