                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#5a5446`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 100, position: `left`,
                                ticks: { color: `#8a8275` }, grid: { color: `rgba(42,38,32,0.06)` },
                                title: { display: true, text: `0–100 / %`, color: `#8a8275` }
                            },
                            x: {
                                ticks: { color: `#8a8275` }, grid: { color: `rgba(42,38,32,0.04)` },
                                title: { display: true, text: `Round`, color: `#8a8275` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.intentHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                signalChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.intentHistory.map((v) => Math.round(v)) },
                        { data: ds.moralityHistory.map((v) => Math.round(v)) },
                        { data: ds.competenceHistory.map((v) => Math.round(v)) },
                        { data: ds.warmthHistory.map((v) => Math.round(v)) }
                    ]
                }
            };
        }

        _composite(ds) {
            // v1.1.0 - verbatim v1.0.0 composite formula (weighted impressions + premium & ROMI bonuses).
            const warmth = Math.round(ds.warmth);
            const competence = Math.round(ds.competence);
            const morality = Math.round(ds.morality);
            const intent = Math.round(ds.intent);
            const romi = Math.round(ds.romi * 100) / 100;
            return Math.round(
                intent * 0.40 + morality * 0.24 + competence * 0.14 + warmth * 0.07 +
                (ds.premiumIntact ? 8 : 0) + Math.max(0, Math.min(15, romi * 7.5))
            );
        }

        formatCompletionMessage(summary) {
            // v1.1.0 FIX B - localized board-debrief scorecard (was: framework default that discarded
            // score, tier, targets and insights).
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? window.mySimulation.t.bind(window.mySimulation)
                : function (k) { return k; };
            summary = summary || {};
            const score = (summary.composite != null) ? summary.composite : (summary.score != null ? summary.score : 0);
            const verdict = summary.gradeKey ? t(summary.gradeKey) : (summary.performance || '');
            const insights = summary.insights || [];
            const chip = function (ok, label) {
                return '<div class="bs-cm-target ' + (ok ? 'bs-cm-met' : 'bs-cm-missed') + '">'
                    + '<span class="bs-cm-tick">' + (ok ? '✓' : '✗') + '</span><span>' + label + '</span></div>';
            };
            const targets = ''
                + chip(!!summary.intentOK, t('tgt_intent'))
                + chip(!!summary.moralityRecovered, t('tgt_morality'))
                + chip(!!summary.premiumIntact, t('tgt_premium'))
                + chip(!!summary.profitable, t('tgt_profit'))
                + chip(!!summary.noGreenwash, t('tgt_nogreenwash'));
            const metric = function (label, val) {
                return '<div class="bs-cm-metric"><span>' + label + '</span><strong>' + val + '</strong></div>';
            };
            const romiStr = (typeof this._fmtRomi === 'function' && summary.romi != null) ? this._fmtRomi(summary.romi) : (summary.romi != null ? summary.romi + '×' : '-');
            const metrics = ''
                + metric(t('kpi_intent'), (summary.intent != null ? summary.intent : '-') + '%')
                + metric(t('kpi_morality'), (summary.morality != null ? summary.morality : '-') + '/100')
                + metric(t('kpi_competence'), (summary.competence != null ? summary.competence : '-') + '/100')
                + metric(t('kpi_warmth'), (summary.warmth != null ? summary.warmth : '-') + '/100')
                + metric(t('kpi_romi'), romiStr);
            const items = insights.map(function (s) { return '<li>' + s + '</li>'; }).join('');
            return ''
                + '<div class="bs-cm">'
                +   '<div class="bs-cm-heading">' + t('comp_heading') + '</div>'
                +   '<div class="bs-cm-verdict">' + verdict + '</div>'
                +   '<div class="bs-cm-score">' + t('comp_score_label') + ': <strong>' + score + '</strong> / 100</div>'
                +   '<div class="bs-cm-sub">' + t('comp_targets_heading') + '</div>'
                +   '<div class="bs-cm-targets">' + targets + '</div>'
                +   '<div class="bs-cm-metrics">' + metrics + '</div>'
                +   (items ? '<ul class="bs-cm-insights">' + items + '</ul>' : '')
                + '</div>';
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function') ? window.mySimulation.t.bind(window.mySimulation) : function (k) { return k; };
            const ds = window.mySimulation.state.domainState;
            const warmth = Math.round(ds.warmth);
            const competence = Math.round(ds.competence);
            const morality = Math.round(ds.morality);
            const intent = Math.round(ds.intent);
            const romi = Math.round(ds.romi * 100) / 100;

            const intentOK = intent >= this.TARGET_INTENT;
            const moralityRecovered = morality >= 58;
            const premiumIntact = ds.premiumIntact;
            const profitable = romi >= 1.0;
            const noGreenwash = !ds.greenwashHit;

            // Composite: intent (the conversion metric) leads, morality matters most among impressions.
            // v1.1.0 FIX A - delegated to _composite(ds) so the persisted per-round score and this
            // completion composite are identical by construction (verbatim v1.0.0 formula).
            const composite = this._composite(ds);

            let pattern = `mixed`;
            if (ds.greenwashHit && morality < 55) pattern = `greenwash`;
            else if (warmth >= 74 && morality < 55) pattern = `wrongmuscle`;
            else if (!premiumIntact) pattern = `pricewar`;
            else if (intentOK && moralityRecovered && premiumIntact && profitable) pattern = `signal`;

            // v1.1.0 FIX C - tier resolved to an i18n key and localized via t() (was hardcoded English).
            let perfKey = `grade_lost`;
            if (intentOK && moralityRecovered && premiumIntact && profitable && noGreenwash && composite >= 75) perfKey = `grade_mastered`;
            else if (intentOK && moralityRecovered && premiumIntact) perfKey = `grade_defended`;
            else if (pattern === `greenwash`) perfKey = `grade_greenwash`;
            else if (pattern === `wrongmuscle`) perfKey = `grade_wrongmuscle`;
            else if (pattern === `pricewar`) perfKey = `grade_pricewar`;
            else if (composite >= 55) perfKey = `grade_mixed`;
            const performance = t(perfKey);

            const insights = [];
            if (intentOK && moralityRecovered && premiumIntact && profitable) insights.push(window.mySimulation.t(`insight_signal`));
            else if (pattern === `greenwash`) insights.push(window.mySimulation.t(`insight_greenwash`));
            else if (pattern === `wrongmuscle`) insights.push(window.mySimulation.t(`insight_wrongmuscle`));
            else if (pattern === `pricewar`) insights.push(window.mySimulation.t(`insight_pricewar`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (!moralityRecovered) insights.push(window.mySimulation.t(`insight_morality_low`));
            if (!intentOK) insights.push(window.mySimulation.t(`insight_intent_low`));
            if (!profitable && ds.spentTotal > 0) insights.push(window.mySimulation.t(`insight_romi_low`));
            if (!ds.builtSubstance) insights.push(window.mySimulation.t(`insight_nosubstance`));

            return {
                gradeKey: perfKey,
                score: composite,
                noGreenwash: noGreenwash,
                warmth: warmth,
                competence: competence,
                morality: morality,
                intent: intent,
                romi: romi,
                intentOK: intentOK,
                moralityRecovered: moralityRecovered,
                premiumIntact: premiumIntact,
                profitable: profitable,
                pattern: pattern,
                composite: composite,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.greenwashHit && ds.morality < 55) return window.mySimulation.t(`hint_greenwash`);
            if (ds.morality < 52) return window.mySimulation.t(`hint_morality`);
            if (ds.warmth >= 74 && ds.morality < 55) return window.mySimulation.t(`hint_wrongmuscle`);
            if (!ds.premiumIntact) return window.mySimulation.t(`hint_premium`);
            if (state.currentPeriod >= 3 && ds.spentTotal > 0 && ds.romi < 0.5) return window.mySimulation.t(`hint_romi`);
            if (ds.intent >= this.TARGET_INTENT && ds.morality >= 58 && ds.premiumIntact) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.morality`, label: `Morality`, i18nKey: `col_morality`, formatter: (v) => `${Math.round(v)}` },
                { key: `results.intent`, label: `Intent`, i18nKey: `col_intent`, formatter: (v) => `${Math.round(v)}%` },
                { key: `results.romi`, label: `ROMI`, i18nKey: `col_romi`, formatter: (v) => self._everSpent() ? self._fmtRomi(v) : `—` }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

        getTranslations() {
            return {
                en: {
                    comp_heading:          `Vista Brand Signal — Board Debrief`,
                    comp_score_label:      `Brand-signal score`,
                    comp_targets_heading:  `Stabilization targets`,
                    tgt_intent:            `Purchase intent ≥60%`,
                    tgt_morality:          `Morality recovered (≥58)`,
                    tgt_premium:           `Premium defended (18%)`,
                    tgt_profit:            `ROMI ≥1.0×`,
                    tgt_nogreenwash:       `No greenwashing backlash`,
